use std::fs
use std::strings

trait Shape {
    fn name(self) -> string
    fn corners(self) -> int
    fn double_area(self) -> int
}

struct Square { s: int }
struct Rect { w: int, h: int }
struct Rtri { a: int, b: int }
struct Trap { a: int, b: int, h: int }

impl Shape for Square {
    fn name(self) -> string { "square" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.s * self.s }
}
impl Shape for Rect {
    fn name(self) -> string { "rect" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { 2 * self.w * self.h }
}
impl Shape for Rtri {
    fn name(self) -> string { "rtri" }
    fn corners(self) -> int { 3 }
    fn double_area(self) -> int { self.a * self.b }
}
impl Shape for Trap {
    fn name(self) -> string { "trap" }
    fn corners(self) -> int { 4 }
    fn double_area(self) -> int { (self.a + self.b) * self.h }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut total = 0
    let mut best = -1
    let mut best_name = "none"
    for line in text.lines() {
        let p = strings::split_whitespace(line)
        if p.len() == 0 { continue }
        let kind = p[0]
        let mut nums: Vec<int> = []
        let mut i = 1
        while i < p.len() {
            nums.push(p[i].parse::<int>().unwrap_or(0))
            i += 1
        }
        let mut name = ""
        let mut c = 0
        let mut d = 0
        if kind == "square" {
            let s = Square { s: nums[0] }
            name = s.name()
            c = s.corners()
            d = s.double_area()
        } else if kind == "rect" {
            let s = Rect { w: nums[0], h: nums[1] }
            name = s.name()
            c = s.corners()
            d = s.double_area()
        } else if kind == "rtri" {
            let s = Rtri { a: nums[0], b: nums[1] }
            name = s.name()
            c = s.corners()
            d = s.double_area()
        } else if kind == "trap" {
            let s = Trap { a: nums[0], b: nums[1], h: nums[2] }
            name = s.name()
            c = s.corners()
            d = s.double_area()
        } else {
            continue
        }
        println("${name} corners=${c} area2=${d}")
        total += d
        if d > best {
            best = d
            best_name = name
        }
    }
    println("total area2=${total}")
    if best < 0 {
        println("largest=none")
    } else {
        println("largest=${best_name} area2=${best}")
    }
}

